mapper.select:
SELECT t1.id, t1.api_key_config_id, t3.key_name AS apiKeyName, t1.vendor_config_id, t2.vendor_name, t1.model_name, t1.input_tokens, t1.output_tokens, t1.cost, t1.request_id, t1.user_id, t1.duration_ms, t1.status, t1.error_message, t1.create_time FROM sys_llm_usage_log t1 LEFT JOIN sys_llm_vendor_config t2 ON t1.vendor_config_id = t2.id AND t2.is_deleted = 0 LEFT JOIN sys_llm_api_key_config t3 ON t1.api_key_config_id = t3.id AND t3.is_deleted = 0
AND t1.model_name LIKE '%' || #{queryParams.modelName} || '%'
AND t1.api_key_config_id = #{queryParams.apiKeyConfigId}
AND t1.vendor_config_id = #{queryParams.vendorConfigId}
AND t1.status = #{queryParams.status}
AND t1.create_time >= #{queryParams.startTime}
AND t1.create_time <= #{queryParams.endTime}
ORDER BY t1.create_time DESC
